apiSecurity,authenticationFramework.authenticationFramework,authenticationFramework.authenticationFramework.apiSecurity,2,1,0,group,policy,{D7},authenticationFramework,,,,"{""apiSecuritySystem"": {""apiGateway"": {""accessControl"": {""rateLimit"": {""global"": {""burstSize"": 50, ""requestsPerSecond"": 1000}, ""perClient"": {""default"": {""burstSize"": 10, ""requestsPerMinute"": 60}, ""premium"": {""burstSize"": 30, ""requestsPerMinute"": 300}}, ""adaptiveThrottling"": {""enabled"": true, ""factors"": [""serverLoad"", ""errorRate"", ""responseTime""]}}, ""authentication"": {""methods"": {""oauth2"": {""flows"": [{""type"": ""clientCredentials"", ""tokenLifetime"": ""1h"", ""scopeValidation"": true}, {""type"": ""authorizationCode"", ""pkceRequired"": true, ""tokenLifetime"": ""15m""}], ""enabled"": true, ""keyManagement"": {""rotation"": {""enabled"": true, ""overlap"": ""1h"", ""interval"": ""24h""}}}, ""mutualTLS"": {""enabled"": true, ""certificateValidation"": {""required"": true, ""ocspStapling"": true, ""revocationCheck"": ""strict""}}}}}, ""inputValidation"": {""dataSanitization"": {""enabled"": true, ""methods"": [{""mode"": ""strict"", ""type"": ""xss"", ""escapeHtml"": true}, {""mode"": ""parameterized"", ""type"": ""sql"", ""escapeSpecialChars"": true}]}, ""validationSchemas"": {""strict"": true, ""enabled"": true, ""schemas"": {""openapi"": {""version"": ""3.1"", ""enforceSpec"": true}, ""jsonSchema"": {""strict"": true, ""version"": ""2020-12""}}, ""customValidators"": {""caching"": true, ""enabled"": true, ""timeout"": ""100ms""}}}}}}","{""apiSecuritySystem"": {""apiGateway"": {""accessControl"": {""rateLimit"": {""global"": {""burstSize"": 50, ""requestsPerSecond"": 1000}, ""perClient"": {""default"": {""burstSize"": 10, ""requestsPerMinute"": 60}, ""premium"": {""burstSize"": 30, ""requestsPerMinute"": 300}}, ""adaptiveThrottling"": {""enabled"": true, ""factors"": [""serverLoad"", ""errorRate"", ""responseTime""]}}, ""authentication"": {""methods"