aws_iam_enterprise_policies,sbosSeeds.D7.config,sbosSeeds.D7.config.aws_iam_enterprise_policies,4,1,0,group,,{D7},sbos_seeds_v1_2026,"AWS IAM Best Practices, AWS Organizations SCPs",,,"{""break_glass"": {""management_account_role"": ""Keep break-glass IAM role with strong MFA and alerting"", ""scp_does_not_apply_to_management_account"": true}, ""description"": ""AWS IAM best practices, SCPs, RCPs, and conditional access for enterprise 2025-2026"", ""industry_stat"": ""85% of breaches involve privilege misuse (Verizon 2025 DBIR)"", ""least_privilege"": {""explicit_deny"": {""overrides_allow"": true, ""use_for_sensitive_actions"": true}, ""avoid_wildcards"": {""s3_example"": ""Use s3:GetObject instead of s3:*""}, ""modular_policies"": {""reduces_complexity"": ""35%""}, ""grant_only_required"": true, ""managed_policy_limit"": ""6144 characters""}, ""monitoring_tools"": {""guardduty"": ""Continuous threat detection"", ""cloudtrail"": ""Full API auditing"", ""security_hub"": ""Centralized security posture"", ""policy_simulator"": ""Test policies before deployment"", ""iam_access_analyzer"": ""Detect overly permissive policies and external access paths""}, ""credential_management"": {""federation"": ""AWS IAM Identity Center (formerly AWS SSO) for centralized workforce identity"", ""mfa_all_humans"": true, ""never_use_root_daily"": true, ""hardware_keys_for_root"": true, ""use_roles_over_access_keys"": true, ""temporary_credentials_auto_rotate"": true}, ""conditional_access_keys"": {""aws_SourceIp"": {""description"": ""Restrict to corporate IP ranges""}, ""gartner_stat"": ""Contextual permissions reduce unauthorized access attempts by over 40%"", ""aws_CurrentTime"": {""description"": ""Limit access to business hours""}, ""aws_ResourceTag"": {""description"": ""ABAC — match principal tags to resource tags""}, ""aws_PrincipalTag"": {""description"": ""ABAC — match based on principal attributes""}, ""aws_SecureTransport"": {""description"": ""Enforce HTTPS only""}, ""aws_MultiFactorAuthPresent"": {""description"": ""Require MFA for sensitive actions""}}, ""service_control_policies"": {""strategies"": {""deny_list"": {""approach"": ""Block specific high-risk actions, FullAWSAccess attached by default"", ""best_for"": ""Lower risk, faster adoption""}, ""allow_list"": {""approach"": ""Explicitly allow only certain services and actions"", ""best_for"": ""Highly regulated environments""}}, ""major_update"": ""September 2025 — Full IAM policy language support for SCPs"", ""common_patterns"": {""restrict_root"": {""principal"": ""arn:aws:iam::*:root"", ""deny_all_actions"": true}, ""data_perimeter"": {""combine"": [""SCPs"", ""RCPs""], ""objectives_achievable"": ""4 of 6""}, ""prevent_leave_org"": {""action"": ""organizations:LeaveOrganization""}, ""region_restriction"": {""description"": ""Deny unapproved regions, exempt global services""}, ""protect_security_services"": {""description"": ""Deny disabling CloudTrail, Config, GuardDuty""}}, ""new_capabilities"": [""Conditions in Allow statements"", ""Individual resource ARNs"", ""NotAction with Allow"", ""NotResource in Allow and Deny"", ""Wildcards anywhere in Action strings""]}, ""resource_control_policies"": {""scope"": ""Organization or OU level"", ""target"": ""Resources (not principals)"", ""controls"": ""Who can access resources, even from outside your org"", ""introduced"": ""November 2024"", ""supported_services"": [""S3"", ""STS"", ""KMS"", ""Secrets Manager"", ""SQS""]}}",{},{},,Configuración aws_iam_enterprise_policies para D7,,,,,,,,,
enterprise_authentication_practices_2026,sbosSeeds.D7.config,sbosSeeds.D7.config.enterprise_authentication_practices_2026,4,1,0,group,,{D7},sbos_seeds_v1_2026,"NIST SP 800-63B-4, Google BeyondCorp, Microsoft Entra ID",,,"{""google_beyondcorp"": {""description"": ""Verify identity, device posture, and contextual risk before granting access"", ""integrations"": [""Crowdstrike Falcon ZTA"", ""Microsoft Intune""], ""access_levels"": ""Custom based on combined device posture data"", ""device_trust_factors"": [""patch_level"", ""compliance_status"", ""os_state""], ""chrome_enterprise_premium"": true}, ""microsoft_entra_id"": {""passkey_support"": ""First-class feature in 2026.04.0 release"", ""zero_trust_pillars"": [""Identity"", ""Device"", ""Apps"", ""Data"", ""Infrastructure"", ""Network"", ""Visibility and Automation""], ""temporary_access_pass"": {""use_once"": true, ""description"": ""Time-limited, single-use, IT-issued for recovery"", ""max_duration"": ""8 hours""}}, ""industry_stats_2026"": {""okta_integrations"": ""8000+ pre-vetted"", ""apps_per_enterprise"": ""101 (Okta Businesses at Work 2025)"", ""help_desk_reduction"": ""81%"", ""enterprise_deployment"": ""87% actively deploying"", ""login_success_passkeys"": ""93%"", ""passkey_accounts_global"": ""15 billion+"", ""login_success_traditional"": ""63%"", ""fortune_500_zero_trust_by_2028"": ""85% (Gartner)""}, ""okta_policy_framework"": {""universal_logout"": {""trigger"": ""Identity Threat Protection (compromised credentials, anomalous behavior, insider threats)"", ""description"": ""Real-time session revocation via Global Token Revocation and OIDC back-channel logout""}, ""three_layer_model"": {""authentication_policies"": {""description"": ""App-specific access control"", ""best_practices"": [""Implement catch-all deny rule in default policy"", ""Enforce phishing-resistant MFA for critical applications"", ""Organize by risk: Low (general), Medium (sensitive), Critical (admin consoles)""], ""auto_assign_new_apps_to_default"": true}, ""global_session_policies"": {""mfa_prompt"": ""at every sign-in (not just new devices)"", ""description"": ""First line of defense for all authentications"", ""best_practices"": [""Set default policy as strict fallback denying access"", ""Require MFA at every sign-in or after MFA lifetime expires"", ""Disable persistent session cookies across browser sessions"", ""Set maximum session lifetimes to prevent gaps""]}, ""oauth_authorization_policies"": {""description"": ""Machine-to-machine security"", ""best_practices"": [""Disable ROPC and implicit grant types"", ""Create specific tightly controlled policies for legacy apps""]}}, ""express_configuration"": {""status"": ""GA 2025-2026"", ""features"": [""OIDC"", ""SCIM"", ""Universal Logout""], ""description"": ""5-click SSO deployment down from 25+ steps""}}, ""recovery_architecture"": {""options_ranked_by_security"": [{""rank"": 1, ""method"": ""Backup passkey on secondary device"", ""description"": ""Encourage enrollment during initial flow""}, {""rank"": 2, ""method"": ""Backup codes generated at enrollment"", ""description"": ""Stored offline by user""}, {""rank"": 3, ""method"": ""Hardware security key as backup"", ""description"": ""For high-assurance environments""}, {""rank"": 4, ""method"": ""Temporary Access Pass"", ""description"": ""Microsoft Entra model, time-limited single-use""}, {""rank"": 5, ""method"": ""Email/phone re-verification"", ""description"": ""Use carefully - reintroduces phishing surface""}], ""recovery_must_not_be_easier_than_auth"": true}, ""passkey_deployment_model"": {""hybrid_model"": {""adoption_rate"": ""47% per FIDO Alliance survey""}, ""consumer_apps"": ""synced passkeys"", ""regulated_workflows"": ""device-bound with smart card form factor"", ""employee_productivity"": ""synced passkeys on managed devices"", ""admin_privileged_access"": ""device-bound hardware security keys""}, ""enrollment_best_practices"": {""copy_text"": ""Sign in faster with your fingerprint — avoid technical jargon"", ""manual_navigation"": {""conversion"": ""10%""}, ""background_upgrade"": {""conversion"": ""15%""}, ""auto_triggered_prompt"": {""trigger"": ""after successful biometric check"", ""conversion"": ""75% of enrollments""}}}",{},{},,Configuración enterprise_authentication_practices_2026 para D7,,,,,,,,,
